  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"./node_modules/@prisma/client\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel CCTV {\n  id               Int      @id @default(autoincrement())\n  address          String\n  purpose          String\n  cameraCount      Int\n  resolution       String\n  direction        String\n  storageDays      Int\n  installationDate DateTime\n  contactNumber    String\n  latitude         Float\n  longitude        Float\n  dataUpdatedAt    DateTime\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Apartment_Details {\n  id                  Int               @id @default(autoincrement())\n  address             String\n  complexType         String\n  complexNamePublic   String?\n  complexNameBuilding String?\n  complexNameRoad     String?\n  complexUniqueId     String            @unique\n  buildingCount       Int\n  landUniqueId        String\n  householdCount      Int\n  approvalDate        DateTime\n  buildingName        String?\n  floorCount          Int\n  latitude            Float\n  longitude           Float\n  marker              Apartment_Marker?\n\n  favorites    Favorite[] // ✅ 연결된 찜 목록\n  transactions Apartment_Transaction[] // 거래 기록\n  reports      Report[] // 보고서\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Apartment_Marker {\n  id              Int                @id @default(autoincrement())\n  complexUniqueId String             @unique\n  latitude        Float\n  longitude       Float\n  details         Apartment_Details? @relation(fields: [complexUniqueId], references: [complexUniqueId])\n  createdAt       DateTime           @default(now())\n  updatedAt       DateTime           @updatedAt\n}\n\nmodel User {\n  id            Int            @id @default(autoincrement())\n  email         String         @unique\n  password      String\n  name          String\n  role          String         @default(\"user\") // \"user\" 또는 \"agent\"\n  phoneNumber   String?\n  profileImage  String?\n  favorites     Favorite[] // ✅ 연결된 찜 목록\n  reports       Report[] // 보고서\n  createdAt     DateTime       @default(now())\n  posts         Post[] // ✅ 이 줄이 필요해!\n  comments      Comment[]\n  notifications Notification[] // ✅ 이 줄을 추가!\n  agent         Agent? // 공인중개사 정보 (role이 \"agent\"인 경우)\n}\n\nmodel Agent {\n  id            String     @id @default(cuid())\n  userId        Int        @unique\n  user          User       @relation(fields: [userId], references: [id])\n  email         String     @unique\n  officeName    String\n  officeAddress String\n  licenseNumber String     @unique\n  properties    Property[]\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n}\n\nmodel Favorite {\n  id              Int      @id @default(autoincrement())\n  userId          Int\n  complexUniqueId String\n  createdAt       DateTime @default(now())\n\n  // ✅ 관계 설정\n  user      User              @relation(fields: [userId], references: [id])\n  apartment Apartment_Details @relation(fields: [complexUniqueId], references: [complexUniqueId])\n\n  @@unique([userId, complexUniqueId])\n}\n\nmodel FindRequest {\n  id        Int      @id @default(autoincrement())\n  phone     String\n  types     String // 예: \"원룸류,기타:고시원\"\n  dealType  String\n  leaseTerm String? // dealType === \"임차\"일 경우만\n  budget    String\n  location  String\n  moveIn    String // 예: \"2주 이내,기타:내년 1월\"\n  note      String?\n  createdAt DateTime @default(now())\n}\n\nmodel SellRequest {\n  id           Int      @id @default(autoincrement())\n  phone        String\n  propertyType String // 체크리스트+기타 합친 값\n  location     String\n  price        String\n  dealType     String // \"매도\" or \"임대\"\n  note         String?\n  createdAt    DateTime @default(now())\n}\n\nmodel Post {\n  id        Int      @id @default(autoincrement())\n  title     String\n  content   String\n  imageUrl  String? // 선택 사항\n  category  String // 예: \"자랑\", \"궁금해요\", \"잡담\"\n  views     Int      @default(0)\n  authorId  Int?\n  createdAt DateTime @default(now())\n\n  author   User?     @relation(fields: [authorId], references: [id])\n  comments Comment[]\n}\n\nmodel Comment {\n  id        Int       @id @default(autoincrement())\n  content   String\n  post      Post      @relation(fields: [postId], references: [id])\n  postId    Int\n  author    User      @relation(fields: [authorId], references: [id])\n  authorId  Int\n  parentId  Int? // ← 대댓글용 (null이면 일반 댓글)\n  children  Comment[] @relation(\"CommentChildren\")\n  parent    Comment?  @relation(\"CommentChildren\", fields: [parentId], references: [id])\n  createdAt DateTime  @default(now())\n}\n\nmodel Notification {\n  id        Int      @id @default(autoincrement())\n  type      String // e.g. \"comment\"\n  message   String\n  user      User     @relation(fields: [userId], references: [id])\n  userId    Int\n  read      Boolean  @default(false)\n  createdAt DateTime @default(now())\n}\n\nmodel Apartment_Transaction {\n  id              Int               @id @default(autoincrement())\n  complexUniqueId String\n  dealAmount      Int // 거래금액\n  dealYear        Int // 거래년도\n  dealMonth       Int // 거래월\n  dealDay         Int // 거래일\n  area            Float // 전용면적\n  floor           Int // 층\n  apartment       Apartment_Details @relation(fields: [complexUniqueId], references: [complexUniqueId])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Report {\n  id              Int               @id @default(autoincrement())\n  complexUniqueId String\n  title           String\n  content         String\n  price           Int\n  status          String            @default(\"pending\") // pending, completed, failed\n  userId          Int\n  apartment       Apartment_Details @relation(fields: [complexUniqueId], references: [complexUniqueId])\n  user            User              @relation(fields: [userId], references: [id])\n  payment         Payment?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Payment {\n  id       Int    @id @default(autoincrement())\n  reportId Int    @unique\n  amount   Int\n  method   String // card, bank_transfer, etc.\n  status   String @default(\"pending\") // pending, completed, failed\n  report   Report @relation(fields: [reportId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Dong_Boundary {\n  id        Int      @id @default(autoincrement())\n  dongName  String   @unique\n  boundary  Json // GeoJSON 형식의 경계 데이터\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Property {\n  id             String    @id @default(cuid())\n  title          String\n  address        String\n  dong           String\n  complexName    String\n  type           String // 매매, 전세, 월세\n  price          Int\n  area           Float\n  pyung          Float\n  floor          Int\n  totalFloors    Int\n  rooms          Int\n  bathrooms      Int\n  maintenanceFee Int\n  direction      String\n  description    String\n  images         Json // String[] 대신 Json 타입 사용\n  isVerified     Boolean   @default(false)\n  isHidden       Boolean   @default(false)\n  lastVerifiedAt DateTime?\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n  agentId        String\n  agent          Agent     @relation(fields: [agentId], references: [id])\n\n  @@index([agentId])\n}\n\nmodel ApiKey {\n  id          Int      @id @default(autoincrement())\n  key         String   @unique\n  name        String\n  description String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n",
